INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Dateiformat dasselbe wie eine Dateiendung?', 2, '[{"text": "Nein", "correct": true, "because": "Format ist Struktur, Endung nur Hinweis"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Dateiformat?', 3, '[{"text": "Daten strukturiert speichern", "correct": true, "because": "Definiert Lesbarkeit"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Kein Netzwerkfokus"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dateiformate sind für Bilder üblich?', 5, '[{"text": "JPEG", "correct": true, "because": "Komprimiertes Bildformat"}, {"text": "PNG", "correct": true, "because": "Unterstützt Transparenz"}, {"text": "TXT", "correct": false, "because": "Textformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dateiformate bestimmen die Kompatibilität. b) Sie sind immer ausführbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle sind Programme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Dateiformats?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Entscheidend für Nutzung"}, {"text": "Kompression", "correct": false, "because": "Beeinflusst Größe"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes Dateiformat komprimiert ist?', 2, '[{"text": "Nein", "correct": true, "because": "Z. B. BMP ist unkomprimiert"}, {"text": "Ja", "correct": false, "because": "Nicht alle sind komprimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format eignet sich für Text?', 3, '[{"text": "TXT", "correct": true, "because": "Einfacher reiner Text"}, {"text": "MP4", "correct": false, "because": "Videoformat"}, {"text": "EXE", "correct": false, "because": "Ausführbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Dateiformat?', 5, '[{"text": "Struktur", "correct": true, "because": "Definiert Datenanordnung"}, {"text": "Kompatibilität", "correct": true, "because": "Bestimmt Öffnung"}, {"text": "Farbe", "correct": false, "because": "Kein Formatmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dateiformate beeinflussen die Größe. b) Sie sind immer proprietär. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele sind offen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Dateiformat?', 4, '[{"text": "Softwareunterstützung", "correct": false, "because": "Zum Öffnen nötig"}, {"text": "Spezifikation", "correct": false, "because": "Definiert Format"}, {"text": "Drucker", "correct": true, "because": "Kein direkter Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PDF nur für Text?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Bilder, Formulare"}, {"text": "Ja", "correct": false, "because": "Vielseitig nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate sind für Audio üblich?', 4, '[{"text": "MP3", "correct": true, "because": "Komprimiertes Audio"}, {"text": "WAV", "correct": true, "because": "Unkomprimiertes Audio"}, {"text": "DOCX", "correct": false, "because": "Textformat"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jedes Format plattformabhängig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Viele sind plattformübergreifend"}, {"text": "Ja", "correct": false, "because": "Z. B. PDF ist universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Formats?', 3, '[{"text": "Zweck", "correct": true, "because": "Muss Nutzung passen"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Kompatibilität wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Formate können Qualität beeinflussen. b) Sie sind immer offen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele sind proprietär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein komprimiertes Format?', 5, '[{"text": "Geringere Größe", "correct": true, "because": "Weniger Speicher"}, {"text": "Schnellere Übertragung", "correct": true, "because": "Kleinere Datenmenge"}, {"text": "Bessere Sicherheit", "correct": false, "because": "Kein Sicherheitsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung unwichtig?', 3, '[{"text": "Softwareunterstützung", "correct": false, "because": "Zum Öffnen nötig"}, {"text": "Dateigröße", "correct": false, "because": "Beeinflusst Speicher"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jedes Format für alle Zwecke geeignet?', 3, '[{"text": "Nein", "correct": true, "because": "Spezifisch für Anwendung"}, {"text": "Ja", "correct": false, "because": "Zweckgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dateiformate verlustfrei sind?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind verlustbehaftet"}, {"text": "Ja", "correct": false, "because": "Z. B. MP3 ist verlustbehaftet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Kompression?', 4, '[{"text": "Reduziert Größe", "correct": true, "because": "Spart Speicherplatz"}, {"text": "Erhöht Qualität", "correct": false, "because": "Kann Qualität mindern"}, {"text": "Ändert Dateiname", "correct": false, "because": "Kein Zusammenhang"}]');
